import{_ as p,a0 as s,w as r,s as l,ao as b,I as a,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Resize Ubuntu Unity Launcher","title":"每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Resize Ubuntu Unity Launcher.md","filePath":"[post].md"}'),o={name:"201311/Daily Ubuntu Tips – Resize Ubuntu Unity Launcher.md"};function U(d,t,m,T,y,g){const u=s("Link");return r(),l("div",null,[t[11]||(t[11]=b('<h1 id="每日ubuntu小技巧-改变ubuntu-unity启动器尺寸" tabindex="-1">每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸 <a class="header-anchor" href="#每日ubuntu小技巧-改变ubuntu-unity启动器尺寸" aria-label="Permalink to “每日Ubuntu小技巧 - 改变Ubuntu Unity启动器尺寸”">​</a></h1><p>这里有一些给新Ubuntu用户的小技巧。这一系列的小技巧是为了帮助Ubuntu新用户轻松地配置和管理他们的电脑。这不是面向专家用户的，只是为了那些刚刚开始使用Ubuntu的用户。</p><p>Ubuntu启动器是Ubuntu Unity桌面的关键部分。启动器是一个布满图标的垂直条，当你登陆的时候，它就会位于屏幕的左边栏。通过它您可以从桌面方便地打开或者启动程序，还可以让您快速访问应用、工作空间、可移动设备和垃圾桶。</p><p>默认情况下，这个启动器图标大小被设置为48X48px，即使是较小的屏幕上也如此。如果你需要调大或调小启动器的尺寸，那么请继续接下来的学习。</p><p>想调整Unity启动器尺寸的原因有很多。其中一个就是为了适应更小的屏幕。如果你的屏幕很小，默认尺寸不合适，那么你就需要改变它了。</p><p>如果图标默认尺寸太小，想要增大它，则可以调整启动器来增大图标，从而容易点击。</p><p>下面开始调整大小，点击右上角的齿轮按钮弹出菜单条，点击系统设置（System Settings...），如下图。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable3.png" alt=""></p><p>接下来，选择 外观（Appearance）</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/unitylauncherubuntu.png" alt=""></p><p>最后，使用滚动条来调整（增大\\减小）启动器的图标尺寸。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/unitylauncherubuntu1.png" alt=""></p><p>这个改变会被自动应用。记住，如果你想要继续作用默认尺寸，移动到48.</p><p>这是另一个为Ubuntu新用户的小技巧。欢迎回来掌握更多的Ubuntu小技巧。如果你是一个老手并且想要做出贡献，就请在下面留言吧。</p><h2 id="享受吧" tabindex="-1">享受吧！ <a class="header-anchor" href="#享受吧" aria-label="Permalink to “享受吧！”">​</a></h2>',15)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-resize-ubuntu-unity-launcher/"},{default:i(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-resize-ubuntu-unity-launcher/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原创翻译，",-1)),e(u,{href:"http://linux.cn/"},{default:i(()=>[...t[3]||(t[3]=[n("Linux中国",-1)])]),_:1}),t[6]||(t[6]=n(" 荣誉推出",-1))]),a("p",null,[t[9]||(t[9]=n("译者：",-1)),e(u,{href:"http://blog.csdn.net/vic___"},{default:i(()=>[...t[7]||(t[7]=[n("Vic___",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),e(u,{href:"https://github.com/jasminepeng"},{default:i(()=>[...t[8]||(t[8]=[n("jasminepeng",-1)])]),_:1})])])}const h=p(o,[["render",U]]);export{_ as __pageData,h as default};
